#!/usr/bin/env python3
"""Verifier for EP-414 proof campaign.
Input: submission directory containing proof.lean (self-contained Lean 4 or mathlib-backed).
Output verdict: pass | fail | invalid (printed as JSON {"verdict":...,"reason":...}).
Checks:
 1. proof.lean exists and is valid UTF-8 (else invalid).
 2. Statement fidelity: the canonical theorem signature must appear verbatim.
 3. No sorry / admit / native_decide / `axiom ` declarations (else fail).
 4. Compile with Lean 4 if toolchain available (lean or elan); compile error => fail.
 5. On success, append `#print axioms ep414` harness and require output axioms subset of standard (propext, Classical.choice, Quot.sound) (else fail).
Environment without any Lean toolchain => invalid (cannot judge).
"""
import json, os, re, shutil, subprocess, sys, tempfile

CANON_SIG = "theorem ep414 : ∀ (m n : ℕ), ∃ (i j : ℕ), iterH i m = iterH j n"
FORBIDDEN = [r"\bsorry\b", r"\badmit\b", r"\bnative_decide\b", r"^\s*axiom\s"]
STANDARD_AX = {"propext", "Classical.choice", "Quot.sound"}

def emit(v, r):
    print(json.dumps({"verdict": v, "reason": r}, ensure_ascii=False))
    sys.exit(0 if v == "pass" else 1)

def find_lean():
    for name in ("lean",):
        p = shutil.which(name)
        if p: return p
    elan = shutil.which("elan")
    if elan:
        try:
            out = subprocess.run([elan, "which", "lean"], capture_output=True, text=True, timeout=60)
            if out.returncode == 0 and out.stdout.strip(): return out.stdout.strip()
        except Exception: pass
    return None

def main():
    args = sys.argv[1:]
    if not args: emit("invalid", "no submission path given")
    sub = args[0]
    f = os.path.join(sub, "proof.lean")
    if not os.path.isfile(f): emit("invalid", "proof.lean missing")
    try:
        src = open(f, encoding="utf-8").read()
    except Exception as e:
        emit("invalid", f"unreadable: {e}")
    if CANON_SIG not in src:
        emit("fail", "statement fidelity: canonical `theorem ep414` signature not found verbatim")
    for pat in FORBIDDEN:
        if re.search(pat, src, flags=re.M):
            emit("fail", f"forbidden token matches /{pat}/")
    lean = find_lean()
    if not lean:
        emit("invalid", "no Lean 4 toolchain in verifier environment")
    with tempfile.TemporaryDirectory() as td:
        work = os.path.join(td, "proof.lean")
        open(work, "w", encoding="utf-8").write(src + "\n#print axioms ep414\n")
        try:
            r = subprocess.run([lean, work], capture_output=True, text=True, timeout=1800)
        except subprocess.TimeoutExpired:
            emit("fail", "lean compile timeout (>1800s)")
        out = (r.stdout or "") + (r.stderr or "")
        if r.returncode != 0:
            emit("fail", "lean compile error: " + out[-800:])
        m = re.search(r"'ep414' does not depend on any axioms", out)
        if m:
            emit("pass", "compiled; no axioms used")
        am = re.search(r"axioms? ([^.]+)", out)
        if am:
            used = {a.strip().rstrip(",") for a in am.group(1).split(",")}
            bad = used - STANDARD_AX
            if bad:
                emit("fail", f"non-standard axioms: {sorted(bad)}")
            emit("pass", f"compiled; axioms={sorted(used & STANDARD_AX)}")
        emit("fail", "compile ok but axioms report unparsable: " + out[-300:])

if __name__ == "__main__":
    main()
